public class TrainedModelInferenceJobFactory(string resourceName = null, Action<Humidifier.CleanRoomsML.TrainedModelInferenceJob> factoryAction = null) : ResourceFactory<Humidifier.CleanRoomsML.TrainedModelInferenceJob>(resourceName)
{

    internal InnerTrainedModelInferenceJobInferenceOutputConfigurationFactory OutputConfigurationFactory { get; set; }

    internal InnerTrainedModelInferenceJobInferenceResourceConfigFactory ResourceConfigFactory { get; set; }

    internal InnerTrainedModelInferenceJobModelInferenceDataSourceFactory DataSourceFactory { get; set; }

    protected override Humidifier.CleanRoomsML.TrainedModelInferenceJob Create()
    {
        var trainedModelInferenceJobResult = CreateTrainedModelInferenceJob();
        factoryAction?.Invoke(trainedModelInferenceJobResult);

        return trainedModelInferenceJobResult;
    }

    private Humidifier.CleanRoomsML.TrainedModelInferenceJob CreateTrainedModelInferenceJob()
    {
        var trainedModelInferenceJobResult = new Humidifier.CleanRoomsML.TrainedModelInferenceJob
        {
            GivenName = InputResourceName,
        };

        return trainedModelInferenceJobResult;
    }
    public override void CreateChildren(Humidifier.CleanRoomsML.TrainedModelInferenceJob result)
    {
        base.CreateChildren(result);

        result.OutputConfiguration ??= OutputConfigurationFactory?.Build();
        result.ResourceConfig ??= ResourceConfigFactory?.Build();
        result.DataSource ??= DataSourceFactory?.Build();
    }

} // End Of Class

